// ① Normalize whatever the audio bridge (or test_webhooks.sh) sent into one clean event.
// Never throws: a bad field gets a safe default, so a live call is never dropped here.
const raw = $input.first().json;
const b = raw.body && typeof raw.body === 'object' ? raw.body : raw;

const toBool = v => v === true || v === 'true' || v === 1;
const clampP = v => Math.max(0, Math.min(3, Math.round(Number(v) || 0)));
const SCAM_TYPES = ['digital_arrest', 'kyc_update', 'bank_impersonation', 'prize_lottery', 'pension_scam', 'relative_emergency', 'utility_disconnection', 'insurance_bonus', 'upi_collect', 'investment_tip', 'sextortion', 'other', 'none'];
const EVENTS = ['telemetry', 'incident', 'escalation', 'call_ended'];

// "+91 98765 43210 - CBI Officer" -> "+919876543210"; bare 10-digit numbers are Indian.
function normalizePhone(p) {
  const m = String(p || '').match(/\+?\d[\d\s\-().]{6,}/);
  if (!m) return '';
  const plus = m[0].trim().startsWith('+');
  let d = m[0].replace(/\D/g, '');
  if (!plus) {
    if (d.startsWith('00')) d = d.slice(2);
    else if (d.length === 11 && d.startsWith('0')) d = '91' + d.slice(1);
    else if (d.length === 10) d = '91' + d;
  }
  return d.length >= 8 && d.length <= 15 ? '+' + d : '';
}

const v = b.verdict && typeof b.verdict === 'object' ? b.verdict : {};
const verdict = {
  scam_type: SCAM_TYPES.includes(v.scam_type) ? v.scam_type : v.scam_type ? 'other' : 'none',
  pressure: clampP(v.pressure ?? b.pressure),
  asks_otp_or_pin: toBool(v.asks_otp_or_pin),
  demands_secrecy: toBool(v.demands_secrecy),
  confidence: Math.max(0, Math.min(1, Number(v.confidence) || 0)),
  language: String(v.language || b.language || '').toLowerCase().slice(0, 5) || 'hi',
  known_scammer: toBool(v.known_scammer ?? b.known_scammer),
  recommended_whisper_clip: String(v.recommended_whisper_clip || 'none'),
  summary_for_family: String(v.summary_for_family || '').slice(0, 600),
  degraded: toBool(v.degraded),
};

// Transcript: [mm:ss] comes from t (seconds since call start), else from unix ts
// relative to the first line. Victim-side 4-8 digit runs are masked again here
// (the bridge already masks OTPs; this is a second lock so no OTP is ever stored).
const mmss = s => {
  const n = Math.max(0, Math.floor(Number(s) || 0));
  return String(Math.floor(n / 60)).padStart(2, '0') + ':' + String(n % 60).padStart(2, '0');
};
const lines = Array.isArray(b.transcript) ? b.transcript : [];
const firstTs = lines.map(x => Number(x && x.ts)).find(n => n > 0);
const hasT = x => x && x.t !== null && x.t !== undefined && x.t !== '' && Number.isFinite(Number(x.t));
const timed = lines.some(x => hasT(x) || Number(x && x.ts) > 0);
const transcript = lines
  .filter(x => x && String(x.text || '').trim())
  .slice(-200)
  .map(x => {
    const t = hasT(x) ? Number(x.t) : firstTs && Number(x.ts) ? Number(x.ts) - firstTs : 0;
    const speaker = x.speaker === 'victim' ? 'victim' : 'caller';
    let text = String(x.text).trim().slice(0, 1000);
    if (speaker === 'victim') text = text.replace(/\b\d{4,8}\b/g, '******');
    return { t: Math.round(t * 10) / 10, ts: Number(x.ts) || null, speaker, text };
  });
const transcript_text = transcript.length && timed
  ? transcript.map(x => `[${mmss(x.t)}] ${x.speaker}: ${x.text}`).join('\n')
  : String(b.transcript_text || transcript.map(x => `${x.speaker}: ${x.text}`).join('\n')).slice(0, 20000);

const pressure = verdict.pressure;
const event = EVENTS.includes(b.event) ? b.event : pressure >= 2 ? 'incident' : 'telemetry';

const hex = n => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const new_incident_id = `${hex(8)}-${hex(4)}-4${hex(3)}-${'89ab'[Math.floor(Math.random() * 4)]}${hex(3)}-${hex(12)}`;

return [{
  json: {
    event,
    event_raw: b.event ?? null,
    call_id: String(b.call_id || '').trim().slice(0, 120) || 'adhoc-' + Date.now(),
    victim_id: String(b.victim_id || '').trim().slice(0, 120) || 'demo-victim-1',
    caller_number: normalizePhone(b.caller_number),
    caller_number_raw: String(b.caller_number || '').slice(0, 80),
    ts: Number(b.ts) || Math.floor(Date.now() / 1000),
    verdict,
    transcript,
    transcript_text,
    call_seconds: transcript.length ? Math.round(transcript[transcript.length - 1].t) : 0,
    new_incident_id,
    received_at: new Date().toISOString(),
  },
}];

// ② -> ③ Merge the three Supabase lookups into ONE context item and decide the route.
// Lookups that failed (Supabase down) arrive as {error}: we note them and carry on,
// so the family alert and the complaint draft still happen.
const ev = $('Normalize Event').first().json;
const errors = [];
// NOTE: every $('...') here takes a literal node name. On n8n 2.22 a Code node that calls
// $(variable) makes the task runner request ALL node types, which fails on the Supabase
// Tool nodes and hangs the execution. Keep node names literal in every Code node.
const grab = (fn, label) => { try { return fn(); } catch (e) { errors.push(label + ': not run'); return []; } };
const clean = (items, label, key) => items.map(i => i.json).filter(r => {
  if (r && r.error) { errors.push(label + ': ' + (r.error.message || r.error)); return false; }
  return r && r[key] !== undefined && r[key] !== null;
});
const scam = clean(grab(() => $('Lookup: caller in scam_numbers').all(), 'scam_numbers'), 'scam_numbers', 'phone_number')[0] || null;
const contacts = clean(grab(() => $('Lookup: trusted_contacts of victim').all(), 'trusted_contacts'), 'trusted_contacts', 'contact_name');
const existing = clean(grab(() => $('Lookup: open incident for call_id').all(), 'incident_evidence'), 'incident_evidence', 'call_id')[0] || null;

const p = ev.verdict.pressure;
const known_scammer = !!scam || ev.verdict.known_scammer === true;

// Route (exactly one Switch output fires, so exactly one webhook reply is sent):
//   existing incident for this call_id  -> escalation (dedupe: a 2nd "incident" is an escalation)
//   incident event or pressure >= 2      -> incident   (also escalation/call_ended that has no row yet)
//   number on the blocklist              -> known_scammer
//   pressure 1                           -> telemetry
//   otherwise                            -> ignore
let route = 'ignore';
if (existing) route = 'escalation';
else if (ev.event === 'incident' || p >= 2) route = 'incident';
else if (known_scammer) route = 'known_scammer';
else if (p >= 1) route = 'telemetry';

// Shared blocklist maths: report_count goes up at most once per call (last_call_id).
const RANK = { low: 0, medium: 1, high: 2, critical: 3 };
const already_counted = !!scam && scam.last_call_id === ev.call_id;
const report_count_before = scam ? Number(scam.report_count) || 0 : 0;
const new_report_count = scam ? (already_counted ? report_count_before : report_count_before + 1) : 1;
let risk_level = new_report_count >= 10 || p >= 3 ? 'critical' : new_report_count >= 3 || p >= 2 ? 'high' : 'medium';
if (scam && RANK[scam.risk_level] > RANK[risk_level]) risk_level = scam.risk_level;

const scam_type = ev.verdict.scam_type !== 'none' ? ev.verdict.scam_type : (scam && scam.scam_type) || 'other';
const family = contacts.filter(c => /^-?\d{5,20}$/.test(String(c.telegram_chat_id || '').trim()));
const victim_name = (contacts[0] && contacts[0].victim_name) || 'your family member';
const victim_language = (contacts[0] && contacts[0].preferred_language) || 'hi';
const callLang = ev.verdict.language;
const local_language = ['hi', 'kn'].includes(callLang) ? callLang : ['hi', 'kn', 'en'].includes(victim_language) ? victim_language : 'hi';

// Escalation: what is new compared with the stored incident?
const prev = existing || {};
const new_flags = [];
if (existing) {
  if (ev.verdict.asks_otp_or_pin && !prev.asks_otp_or_pin) new_flags.push('otp');
  if (ev.verdict.demands_secrecy && !prev.demands_secrecy) new_flags.push('secrecy');
  if (p > (Number(prev.max_pressure) || 0)) new_flags.push('pressure');
  if (known_scammer && !prev.known_scammer) new_flags.push('known_scammer');
}
const prevLines = Array.isArray(prev.transcript_json) ? prev.transcript_json.length : 0;

return [{
  json: {
    ...ev,
    route,
    known_scammer,
    scam_type,
    scam_record: scam,
    already_counted,
    report_count_before,
    new_report_count,
    risk_level,
    contacts,
    family,
    victim_name,
    victim_language,
    local_language,
    incident_id: existing ? existing.id : ev.new_incident_id,
    existing_incident: existing
      ? { id: existing.id, max_pressure: existing.max_pressure, complaint_status: existing.complaint_status,
          asks_otp_or_pin: existing.asks_otp_or_pin, demands_secrecy: existing.demands_secrecy, transcript_lines: prevLines }
      : null,
    new_flags,
    escalation_notify: route === 'escalation' && (new_flags.length > 0 || ev.event === 'call_ended') && prev.complaint_status !== 'submitted',
    lookup_errors: errors,
    lookups_ok: errors.length === 0,
  },
}];

// Lane A: the family hears about it NOW, before any AI runs. One item per trusted
// contact that has a Telegram chat id. No contacts -> no items -> the lane just ends
// (the incident reply then says family_alerted: false and the app tells the victim).
const c = $('Build Incident Context').first().json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const LABEL = {
  digital_arrest: 'Digital-arrest scam (fake police / CBI)',
  kyc_update: 'Fake KYC-update call',
  bank_impersonation: 'Fake bank call',
  prize_lottery: 'Lottery / prize scam',
  pension_scam: 'Pension / life-certificate scam',
  relative_emergency: 'Fake family-emergency call (relative "in trouble")',
  utility_disconnection: 'Fake electricity-disconnection call',
  insurance_bonus: 'Fake insurance bonus / maturity call',
  upi_collect: 'UPI "receive money" trap (PIN / QR / collect request)',
  investment_tip: 'Investment / stock-tips scam',
  sextortion: 'Sextortion threat (fake obscene video)',
  other: 'Scam call',
  none: 'Suspicious call',
};
const flags = [
  c.verdict.asks_otp_or_pin && 'asking for an OTP / PIN',
  c.verdict.demands_secrecy && 'telling them to keep it secret',
  c.known_scammer && (c.report_count_before ? `number already reported ${c.report_count_before}x` : 'number flagged as a known scammer'),
].filter(Boolean);
const who = esc(c.victim_name);

return c.family.map(f => ({
  json: {
    chat_id: String(f.telegram_chat_id).trim(),
    contact_name: f.contact_name,
    incident_id: c.incident_id,
    text: [
      `🚨 <b>Chaukanna: ${who} is on a scam call right now</b>`,
      `• ${esc(LABEL[c.verdict.scam_type] || 'Scam call')} from ${esc(c.caller_number || 'an unknown number')}` +
        (flags.length ? ` — ${esc(flags.join(', '))}` : ''),
      `• Pressure ${c.verdict.pressure}/3. Chaukanna has already whispered a warning to ${who}.`,
      `• Call ${who} now. Police never "arrest" anyone on a call, and nobody genuine asks for an OTP.`,
    ].join('\n'),
  },
}));

