// Runs only if the AI Agent failed (both Gemini models down, quota, bad JSON).
// Builds the same output shape from the transcript with keyword rules, so the
// incident reply, the evidence row and the approval step never depend on the LLM.
const c = $('Build Incident Context').first().json;
const errIn = $input.first().json;
const aiError = String((errIn.error && (errIn.error.message || errIn.error)) || errIn.message || 'AI agent failed').slice(0, 300);

// Priority order: the first category that matches a caller line wins for that line.
const RULES = [
  ['otp_demand', /(otp|ओटीपी|ओ\.?टी\.?पी|\bpin\b|पिन|ಒಟಿಪಿ|cvv|password|पासवर्ड|verification code)/i],
  ['money_demand', /(transfer|ट्रांसफर|paisa|पैसा|पैसे|rupees|रुपये|₹|upi|safe account|सेफ अकाउंट|ಹಣ|ವರ್ಗಾ)/i],
  ['secrecy_demand', /(kisi ko|किसी को|mat bata|मत बता|secret|गोपनीय|ಯಾರಿಗೂ|don'?t tell|do not tell|confidential|disconnect|कॉल मत काट|call mat kaat)/i],
  ['arrest_threat', /(arrest|अरेस्ट|गिरफ्तार|giraftaar|warrant|वारंट|ಅರೆಸ್ಟ್|ಬಂಧ|jail|जेल|laundering|लॉन्ड्रिंग|case|केस|fir\b)/i],
  ['impersonation', /(cbi|सीबीआई|police|पुलिस|ಪೊಲೀಸ್|officer|अधिकारी|ಅಧಿಕಾರಿ|inspector|इंस्पेक्टर|customs|कस्टम|rbi|trai|court|अदालत|narcotics|bank|बैंक)/i],
];
const LABEL_EN = {
  otp_demand: 'demanded an OTP / PIN', money_demand: 'demanded a money transfer', secrecy_demand: 'demanded secrecy',
  arrest_threat: 'threatened arrest / a criminal case', impersonation: 'impersonated an official',
};
const mmss = s => { const n = Math.max(0, Math.floor(Number(s) || 0)); return String(Math.floor(n / 60)).padStart(2, '0') + ':' + String(n % 60).padStart(2, '0'); };
const lines = (c.transcript || []).filter(x => x.speaker === 'caller');
const evidence = [];
for (const x of lines) {
  const hit = RULES.find(([, rx]) => rx.test(x.text));
  if (hit) evidence.push({ timestamp: mmss(x.t), speaker: 'caller', category: hit[0], quote: x.text.slice(0, 160) });
}
const ev = evidence.slice(0, 8);
const has = k => ev.some(e => e.category === k);

const SCAM_EN = { digital_arrest: 'digital-arrest scam', kyc_update: 'KYC-update fraud', bank_impersonation: 'bank-impersonation fraud', prize_lottery: 'lottery / prize fraud', pension_scam: 'pension / life-certificate fraud', relative_emergency: 'fake family-emergency fraud', utility_disconnection: 'electricity-disconnection fraud', insurance_bonus: 'insurance-bonus fraud', upi_collect: 'UPI collect-request fraud', investment_tip: 'investment fraud', sextortion: 'sextortion', other: 'phone fraud', none: 'phone fraud' };
const SCAM_HI = { digital_arrest: 'डिजिटल अरेस्ट धोखाधड़ी', kyc_update: 'KYC अपडेट धोखाधड़ी', bank_impersonation: 'फ़र्ज़ी बैंक कॉल धोखाधड़ी', prize_lottery: 'लॉटरी / इनाम धोखाधड़ी', pension_scam: 'पेंशन / जीवन प्रमाण धोखाधड़ी', relative_emergency: 'फ़र्ज़ी पारिवारिक आपात धोखाधड़ी', utility_disconnection: 'बिजली कनेक्शन काटने की धोखाधड़ी', insurance_bonus: 'बीमा बोनस धोखाधड़ी', upi_collect: 'यूपीआई कलेक्ट रिक्वेस्ट धोखाधड़ी', investment_tip: 'निवेश धोखाधड़ी', sextortion: 'सेक्सटॉर्शन (अश्लील वीडियो से ब्लैकमेल)', other: 'फ़ोन धोखाधड़ी', none: 'फ़ोन धोखाधड़ी' };
const SCAM_KN = { digital_arrest: 'ಡಿಜಿಟಲ್ ಅರೆಸ್ಟ್ ವಂಚನೆ', kyc_update: 'KYC ಅಪ್‌ಡೇಟ್ ವಂಚನೆ', bank_impersonation: 'ನಕಲಿ ಬ್ಯಾಂಕ್ ಕರೆ ವಂಚನೆ', prize_lottery: 'ಲಾಟರಿ / ಬಹುಮಾನ ವಂಚನೆ', pension_scam: 'ಪಿಂಚಣಿ / ಜೀವನ ಪ್ರಮಾಣಪತ್ರ ವಂಚನೆ', relative_emergency: 'ನಕಲಿ ಕುಟುಂಬ ತುರ್ತು ವಂಚನೆ', utility_disconnection: 'ವಿದ್ಯುತ್ ಸಂಪರ್ಕ ಕಡಿತ ವಂಚನೆ', insurance_bonus: 'ವಿಮಾ ಬೋನಸ್ ವಂಚನೆ', upi_collect: 'ಯುಪಿಐ ಕಲೆಕ್ಟ್ ರಿಕ್ವೆಸ್ಟ್ ವಂಚನೆ', investment_tip: 'ಹೂಡಿಕೆ ವಂಚನೆ', sextortion: 'ಸೆಕ್ಸ್‌ಟಾರ್ಶನ್ (ಅಶ್ಲೀಲ ವಿಡಿಯೋ ಬ್ಲ್ಯಾಕ್‌ಮೇಲ್)', other: 'ಫೋನ್ ವಂಚನೆ', none: 'ಫೋನ್ ವಂಚನೆ' };

const when = $now.setZone('Asia/Kolkata').toFormat('dd LLL yyyy, HH:mm') + ' IST';
const num = c.caller_number || 'an unknown number';
const name = c.victim_name;
const st = c.scam_type || 'other';
const evLines = ev.length
  ? ev.map((e, i) => `${i + 1}. [${e.timestamp}] The caller ${LABEL_EN[e.category]}: "${e.quote}"`).join('\n')
  : '1. The caller pressured me throughout the call (see the attached transcript).';
const evQuotes = ev.length ? ev.map((e, i) => `${i + 1}. [${e.timestamp}] “${e.quote}”`).join('\n') : '1. —';
const ref = `Chaukanna incident ${c.incident_id}`;

const complaint_en = [
  'To,',
  'The Officer-in-charge, National Cyber Crime Reporting Portal (cybercrime.gov.in) / Helpline 1930',
  '',
  `Subject: Complaint about an attempted ${SCAM_EN[st]} over a phone call from ${num}`,
  '',
  'Sir / Madam,',
  `I, ${name}, received a phone call on ${when} from ${num}. The caller pretended to be an official and tried to frighten me into following instructions. The key moments of the call, with timestamps from the start of the call, are:`,
  evLines,
  '',
  `${has('otp_demand') ? 'I did not share any OTP or PIN. ' : ''}No money was transferred. I request you to trace and block this number and take action against the people behind it.`,
  `Call recording transcript with timestamps is preserved as evidence (${ref}).`,
  '',
  'Yours faithfully,',
  name,
].join('\n');

const complaint_hi = [
  'सेवा में,',
  'प्रभारी अधिकारी, राष्ट्रीय साइबर अपराध रिपोर्टिंग पोर्टल (cybercrime.gov.in) / हेल्पलाइन 1930',
  '',
  `विषय: ${num} से आई फ़ोन कॉल द्वारा ${SCAM_HI[st]} के प्रयास की शिकायत`,
  '',
  'महोदय / महोदया,',
  `मैं, ${name}, यह शिकायत दर्ज कर रही/रहा हूँ। ${when} को मुझे ${num} से एक कॉल आई। कॉल करने वाले ने खुद को सरकारी अधिकारी बताया और मुझे डराकर अपनी बात मनवाने की कोशिश की। कॉल के मुख्य अंश (कॉल शुरू होने से समय सहित):`,
  evQuotes,
  '',
  `${has('otp_demand') ? 'मैंने कोई OTP या PIN साझा नहीं किया। ' : ''}कोई पैसा ट्रांसफर नहीं किया गया। कृपया इस नंबर का पता लगाकर इसे ब्लॉक करें और इसके पीछे के लोगों पर कार्रवाई करें।`,
  `समय सहित कॉल का ट्रांसक्रिप्ट साक्ष्य के रूप में सुरक्षित है (${ref})।`,
  '',
  'भवदीय / भवदीया,',
  name,
].join('\n');

const complaint_kn = [
  'ಗೆ,',
  'ಪ್ರಭಾರಿ ಅಧಿಕಾರಿ, ರಾಷ್ಟ್ರೀಯ ಸೈಬರ್ ಅಪರಾಧ ವರದಿ ಪೋರ್ಟಲ್ (cybercrime.gov.in) / ಸಹಾಯವಾಣಿ 1930',
  '',
  `ವಿಷಯ: ${num} ಸಂಖ್ಯೆಯಿಂದ ಬಂದ ಫೋನ್ ಕರೆಯ ಮೂಲಕ ${SCAM_KN[st]} ಪ್ರಯತ್ನದ ಬಗ್ಗೆ ದೂರು`,
  '',
  'ಮಾನ್ಯರೇ,',
  `ನಾನು, ${name}, ಈ ದೂರನ್ನು ಸಲ್ಲಿಸುತ್ತಿದ್ದೇನೆ. ${when} ರಂದು ${num} ಸಂಖ್ಯೆಯಿಂದ ನನಗೆ ಕರೆ ಬಂದಿತು. ಕರೆ ಮಾಡಿದವರು ತಮ್ಮನ್ನು ಸರ್ಕಾರಿ ಅಧಿಕಾರಿ ಎಂದು ಹೇಳಿಕೊಂಡು ನನ್ನನ್ನು ಹೆದರಿಸಿದರು. ಕರೆಯ ಮುಖ್ಯ ಭಾಗಗಳು (ಕರೆ ಆರಂಭದಿಂದ ಸಮಯದೊಂದಿಗೆ):`,
  evQuotes,
  '',
  `${has('otp_demand') ? 'ನಾನು ಯಾವುದೇ OTP ಅಥವಾ PIN ಹಂಚಿಕೊಂಡಿಲ್ಲ. ' : ''}ಯಾವುದೇ ಹಣ ವರ್ಗಾಯಿಸಲಾಗಿಲ್ಲ. ದಯವಿಟ್ಟು ಈ ಸಂಖ್ಯೆಯನ್ನು ಪತ್ತೆಹಚ್ಚಿ ನಿರ್ಬಂಧಿಸಿ ಮತ್ತು ಸೂಕ್ತ ಕ್ರಮ ಕೈಗೊಳ್ಳಿ.`,
  `ಸಮಯದೊಂದಿಗೆ ಕರೆಯ ಪ್ರತಿಲಿಪಿಯನ್ನು ಸಾಕ್ಷ್ಯವಾಗಿ ಸಂರಕ್ಷಿಸಲಾಗಿದೆ (${ref}).`,
  '',
  'ಇಂತಿ,',
  name,
].join('\n');

const lang = c.local_language;
const worst = ev.find(e => e.category === 'otp_demand') || ev.find(e => e.category === 'money_demand') || ev.find(e => e.category === 'arrest_threat') || ev[0];
return [{
  json: {
    draft_source: 'template',
    ai_error: aiError,
    output: {
      family_alert_bullets: [
        `${name} got a ${SCAM_EN[st]} call from ${num}; the caller posed as an official.`,
        worst ? `At [${worst.timestamp}] the caller ${LABEL_EN[worst.category]}.` : 'The caller kept up heavy pressure on the call.',
        `Call ${name} now and make sure no OTP or money was shared. Complaint draft is ready for approval.`,
      ],
      complaint_subject: `Attempted ${SCAM_EN[st]} from ${num}`,
      complaint_en,
      complaint_local: lang === 'kn' ? complaint_kn : lang === 'en' ? complaint_en : complaint_hi,
      local_language: ['hi', 'kn', 'en'].includes(lang) ? lang : 'hi',
      key_evidence: ev,
    },
  },
}];

// Takes the AI Agent's structured output (or the template fallback) and checks every
// [mm:ss] it cites against the real transcript. Unverified timestamps are reported,
// not hidden: the human sees them before approving the complaint.
const c = $('Build Incident Context').first().json;
const j = $input.first().json;
let out = j.output;
if (typeof out === 'string') { try { out = JSON.parse(out); } catch (e) { out = {}; } }
out = out && typeof out === 'object' ? out : {};
const source = j.draft_source || 'ai';

const norm = s => String(s || '').replace(/[\[\]\s]/g, '');
const stamps = new Set((String(c.transcript_text).match(/\[\d{2}:\d{2}\]/g) || []).map(norm));
// Only bracketed [mm:ss] tokens count as citations (a clock time like 20:01 IST is not one).
const citedIn = txt => [...new Set((String(txt || '').match(/\[\d{2}:\d{2}\]/g) || []).map(norm))];
const cited = citedIn(out.complaint_en);
const verified = cited.filter(t => stamps.has(t));
const unverified = cited.filter(t => !stamps.has(t));

const strip = s => String(s || '').replace(/^[\s•\-*·]+/, '').replace(/\*\*/g, '').trim();
const bullets = (Array.isArray(out.family_alert_bullets) ? out.family_alert_bullets : String(out.family_alert_bullets || '').split('\n'))
  .map(strip).filter(Boolean).slice(0, 3);
const pad = [
  `${c.victim_name} received a scam call from ${c.caller_number || 'an unknown number'}.`,
  'The caller pressured them on the call.',
  `Call ${c.victim_name} now and make sure no OTP or money was shared.`,
];
while (bullets.length < 3) bullets.push(pad[bullets.length]);

const lang = ['hi', 'kn', 'en'].includes(out.local_language) ? out.local_language : c.local_language;
const complaint_en = strip(out.complaint_en) ? String(out.complaint_en).replace(/\*\*/g, '').trim() : '';
const complaint_local = String(out.complaint_local || '').replace(/\*\*/g, '').trim() || complaint_en;
const key_evidence = (Array.isArray(out.key_evidence) ? out.key_evidence : [])
  .map(e => ({ timestamp: norm(e.timestamp), speaker: e.speaker || 'caller', category: e.category || 'other_coercion', quote: String(e.quote || '').slice(0, 200) }))
  .filter(e => stamps.has(e.timestamp));

return [{
  json: {
    incident_id: c.incident_id,
    call_id: c.call_id,
    draft_source: source,
    ai_error: j.ai_error || null,
    complaint_subject: String(out.complaint_subject || '').trim(),
    complaint_en,
    complaint_local,
    language: lang,
    family_alert_bullets: bullets,
    family_alert: bullets.map(b => '• ' + b).join('\n'),
    key_evidence,
    citations: { cited: cited.length, verified: verified.length, unverified },
  },
}];

// The synchronous reply the audio bridge waits for (CONTRACTS.md §2). Lanes A-C ran
// before this lane (n8n v1 execution order runs parallel branches top to bottom), so
// their results are read here to report what actually happened, not what was hoped.
const c = $('Build Incident Context').first().json;
const d = $('Verify citations & assemble draft').first().json;
// Literal node names only (see the note in Build Incident Context).
const safe = fn => { try { return fn(); } catch (e) { return []; } };
const okRows = items => items.map(i => i.json).filter(r => r && !r.error && Object.keys(r).length > 0);
const tg = okRows(safe(() => $('Telegram: alert family now').isExecuted ? $('Telegram: alert family now').all() : []));
const evidence = okRows(safe(() => $('Log evidence to incident_evidence').isExecuted ? $('Log evidence to incident_evidence').all() : []));
const bump = okRows(safe(() => $('Upsert: bump report_count').isExecuted ? $('Upsert: bump report_count').all() : []));
const add = okRows(safe(() => $('Upsert: add caller to blocklist').isExecuted ? $('Upsert: add caller to blocklist').all() : []));
const draft = okRows(safe(() => $('Save draft as draft_pending_human').isExecuted ? $('Save draft as draft_pending_human').all() : []));
const family_alerted = tg.some(r => r.ok === true || r.result || r.message_id);
const evidence_saved = evidence.some(r => r.id);
const blocklisted = [...bump, ...add].some(r => r.phone_number);
const draft_saved = draft.some(r => r.id);

const resumeUrl = $execution.resumeUrl;
const base = String(resumeUrl || '').split('/webhook-waiting/')[0];

return [{
  json: {
    ok: true,
    incident_id: c.incident_id,
    call_id: c.call_id,
    known_scammer: c.known_scammer,
    family_alerted,
    evidence_saved,
    blocklisted,
    complaint_draft: { en: d.complaint_en, local: d.complaint_local, language: d.language },
    family_alert: d.family_alert,
    approve_url: resumeUrl,
    // additive fields (optional for clients)
    approve_fallback_url: base ? base + '/webhook/chaukanna-approve' : null,
    draft_saved,
    draft_source: d.draft_source,
    citations: d.citations,
    key_evidence: d.key_evidence,
    scam_type: c.scam_type,
    max_pressure: c.verdict.pressure,
    report_count: c.new_report_count,
    risk_level: c.risk_level,
    lookups_ok: c.lookups_ok,
  },
}];

// After the reply is sent: the AI's 3-bullet brief goes to every trusted contact.
const c = $('Build Incident Context').first().json;
const d = $('Verify citations & assemble draft').first().json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const LANG = { hi: 'Hindi', kn: 'Kannada', en: 'English' };
const text = [
  `📝 <b>Chaukanna incident brief — ${esc(c.victim_name)}</b>`,
  esc(d.family_alert),
  '',
  `A 1930 / cybercrime.gov.in complaint is drafted in English${d.language !== 'en' ? ' and ' + (LANG[d.language] || d.language) : ''}` +
    ` with ${d.citations.verified} timestamped quotes. It is filed only after ${esc(c.victim_name)} taps Approve in the app.`,
  `<i>Incident ${esc(c.incident_id)}</i>`,
].join('\n');
return c.family.map(f => ({ json: { chat_id: String(f.telegram_chat_id).trim(), incident_id: c.incident_id, text } }));

// Shared by both approval paths (in-app resume URL and approve-by-call_id).
// Reads whichever "Prepare approval" node ran, plus the Supabase update result.
// Literal node names only (see the note in Build Incident Context).
const ran = fn => { try { return fn(); } catch (e) { return false; } };
const prep = ran(() => $('Prepare approval (in-app resume)').isExecuted) ? $('Prepare approval (in-app resume)').first().json
  : ran(() => $('Prepare approval (by call_id)').isExecuted) ? $('Prepare approval (by call_id)').first().json : {};
const row = $input.first().json || {};
const recorded = !!row.id && row.complaint_status === 'submitted';
return [{
  json: {
    ok: true,
    incident_id: prep.incident_id,
    call_id: prep.call_id,
    victim_id: row.victim_id || prep.victim_id,
    caller_number: row.caller_number || prep.caller_number || '',
    complaint_status: 'submitted',
    recorded,
    db_error: row.error ? String(row.error.message || row.error).slice(0, 200) : null,
    approved_via: prep.approved_via,
    submitted_at: prep.submitted_at,
  },
}];

// The final receipt to the family chat. Honest wording: cybercrime.gov.in has no
// public filing API, so "submitted" means the victim approved it and it is recorded
// with the evidence; the family gets the incident id to quote on 1930.
const r = $('Approval result').first().json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const contacts = $input.all().map(i => i.json).filter(x => x && /^-?\d{5,20}$/.test(String(x.telegram_chat_id || '').trim()));
const name = (contacts[0] && contacts[0].victim_name) || 'Your family member';
const when = $now.setZone('Asia/Kolkata').toFormat('dd LLL yyyy, HH:mm') + ' IST';
const text = [
  `✅ <b>1930 complaint approved — ${esc(name)}</b>`,
  `• ${esc(name)} approved the complaint about the call from ${esc(r.caller_number || 'the scam number')} at ${when}.`,
  `• Status: submitted${r.recorded ? ' and saved with the call evidence' : ' (evidence store unreachable; keep this message)'}.`,
  `• Quote incident <code>${esc(r.incident_id)}</code> on 1930 or at cybercrime.gov.in. If any money moved, call the bank first.`,
].join('\n');
return contacts.map(x => ({ json: { chat_id: String(x.telegram_chat_id).trim(), text } }));

// Escalation / call ended: update the existing evidence row (never a second row).
// Only fields that are present are sent. The database keeps max_pressure and the
// OTP/secrecy flags monotonic, so a lower value here can never erase evidence.
const c = $input.first().json;
const patch = {
  max_pressure: c.verdict.pressure,
  asks_otp_or_pin: c.verdict.asks_otp_or_pin,
  demands_secrecy: c.verdict.demands_secrecy,
  last_event: c.event,
};
if (c.known_scammer) patch.known_scammer = true;
if (c.verdict.scam_type !== 'none') patch.scam_type = c.verdict.scam_type;
const prevLines = (c.existing_incident && c.existing_incident.transcript_lines) || 0;
if (c.transcript.length && c.transcript.length >= prevLines) patch.transcript_json = c.transcript;
return [{ json: patch }];

// Tell the family what changed (new red flag) or that the call has ended.
const c = $('Build Incident Context').first().json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const mmss = s => { const n = Math.max(0, Math.floor(Number(s) || 0)); return String(Math.floor(n / 60)).padStart(2, '0') + ':' + String(n % 60).padStart(2, '0'); };
const who = esc(c.victim_name);
const lastCaller = [...c.transcript].reverse().find(x => x.speaker === 'caller');
const FLAG = {
  otp: 'is now asking for an OTP / PIN',
  secrecy: 'is telling them to keep it secret',
  pressure: `pushed the pressure to ${c.verdict.pressure}/3`,
  known_scammer: 'is calling from a number already on the scam list',
};
let text;
if (c.event === 'call_ended') {
  text = [
    `📞 <b>${who}'s scam call has ended</b>`,
    `• Call length about ${mmss(c.call_seconds)}. The full transcript is saved as evidence.`,
    `• A 1930 complaint draft is waiting for ${who}'s approval in the Chaukanna app.`,
    `• Please call ${who} and stay with them for a few minutes.`,
  ].join('\n');
} else {
  text = [
    `⚠️ <b>Escalation on ${who}'s call</b>`,
    `• The caller ${esc(c.new_flags.map(f => FLAG[f]).filter(Boolean).join(' and '))}.`,
    lastCaller ? `• Latest at [${mmss(lastCaller.t)}]: “${esc(lastCaller.text.slice(0, 140))}”` : '• The call is still going.',
    `• Call ${who} now.`,
  ].join('\n');
}
return c.family.map(f => ({ json: { chat_id: String(f.telegram_chat_id).trim(), incident_id: c.incident_id, text } }));

// ⑦ Approve by call_id: pick the incident the app means and decide how to approve it.
// Match priority: incident_id, then call_id, then (older app builds that send neither)
// the newest pending incident from the same caller in the last 2 hours.
const body = $('Webhook: chaukanna-approve').first().json.body || {};
const all = $input.all().map(i => i.json);
const dbError = all.find(r => r && r.error);
const rows = all.filter(r => r && r.id && !r.error);

const digits = String(body.caller_number || '').replace(/\D/g, '');
const caller = digits.length === 10 ? '+91' + digits : digits ? '+' + digits : '';
const recent = r => Date.now() - new Date(r.created_at).getTime() < 2 * 3600 * 1000;
const newest = (a, b) => new Date(b.created_at) - new Date(a.created_at);

const pick =
  (body.incident_id && rows.find(r => r.id === body.incident_id)) ||
  (body.call_id && rows.find(r => r.call_id === body.call_id)) ||
  (!body.incident_id && !body.call_id && caller &&
    rows.filter(r => r.caller_number === caller && r.complaint_status === 'draft_pending_human' && recent(r)).sort(newest)[0]) ||
  null;

const confirmed = body.confirmed_by_human === true || body.confirmed_by_human === 'true';
let route;
if (!confirmed) route = 'not_confirmed';
else if (!pick) route = dbError ? 'db_error' : 'not_found';
else if (pick.complaint_status === 'submitted') route = 'already_submitted';
else if (pick.approve_url) route = 'resume';
else route = 'direct';

return [{
  json: {
    route,
    approve_url: pick ? pick.approve_url : null,
    incident: pick ? { id: pick.id, call_id: pick.call_id, victim_id: pick.victim_id, caller_number: pick.caller_number, submitted_at: pick.submitted_at } : null,
    body: { ...body, approved_via: 'call_id' },
    reason: {
      not_confirmed: 'confirmed_by_human must be true',
      not_found: 'no incident matches this call_id / incident_id',
      db_error: 'evidence store unreachable: ' + String(dbError && (dbError.error.message || dbError.error)).slice(0, 160),
    }[route] || null,
    status_code: { not_confirmed: 400, not_found: 404, db_error: 503 }[route] || 200,
  },
}];

// ⑧ A family member tapped an inline button on an alert. callback_data is
// "ack:<incident uuid>" (I'm calling them now) or "fa:<incident uuid>" (false alarm).
const q = $input.first().json.callback_query || {};
const [kind, id] = String(q.data || '').split(':');
const incident_id = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id || '') ? id : null;
const who = [q.from && q.from.first_name, q.from && q.from.last_name].filter(Boolean).join(' ') || 'Family member';
const response = kind === 'ack' ? 'ack' : kind === 'fa' ? 'false_alarm' : 'unknown';
return [{
  json: {
    query_id: q.id,
    incident_id: incident_id || '00000000-0000-0000-0000-000000000000',
    family_response: `${response} by ${who}`.slice(0, 120),
    toast: response === 'ack' ? `Thanks ${who}. Logged: you are calling them now.`
      : response === 'false_alarm' ? 'Logged as a possible false alarm. Nothing is filed without approval.'
      : 'This button has expired.',
  },
}];

// ⑨ Catch-all: this workflow is its own error workflow (Settings -> Error workflow).
// Put the Telegram chat id of whoever runs the demo here to get failure alerts.
const OPS_TELEGRAM_CHAT_ID = '';

const e = $input.first().json;
const x = e.execution || {};
const text = [
  '⚠️ <b>Chaukanna automation failed</b>',
  `Node: ${x.lastNodeExecuted || 'unknown'}`,
  `Error: ${String((x.error && x.error.message) || 'unknown').slice(0, 300)}`,
  `Execution: ${x.url || x.id || 'n/a'}`,
  'If a scam call is in progress, phone the family directly.',
].join('\n');
return [{ json: { ops_chat_id: OPS_TELEGRAM_CHAT_ID, text, execution_id: x.id || null, failed_node: x.lastNodeExecuted || null } }];
